import { toggleNotifications } from './actions'

export default async function Home() {
  const enabled = await getNotificationPreference()

  return (
    <main>
      <h1>Settings</h1>
      <form action={toggleNotifications}>
        <label>
          <input type="checkbox" checked={enabled} readOnly />
          Notifications: {enabled ? 'On' : 'Off'}
        </label>
        <button type="submit">
          Toggle notifications
        </button>
      </form>
    </main>
  )
}

async function getNotificationPreference() {
  const { notificationsEnabled } = await import('./actions')
  return notificationsEnabled
}

